{
  "aktywnosci": [
    {
      "tytul": "Kolorowe skojarzenia – zabawa z przedmiotami",
      "opis": "Przygotuj kosz z różnokolorowymi przedmiotami (klocki, szarfy, liście, piłeczki). Nauczyciel pokazuje jeden przedmiot w wyrazistym kolorze (np. czerwony), a dzieci mają znaleźć w sali coś w tym samym kolorze i przynieść do koła. Potem siadamy w kręgu i każde dziecko mówi, co znalazło. Zabawa trwa, aż omówimy kilka kolorów. Wariant: zamiast szukać, dzieci mogą wskazać na sobie ubranie w danym kolorze."
    },
    {
      "tytul": "Taniec kolorów – improwizacja ruchowa z chustą",
      "opis": "Rozłóż na podłodze dużą chustę animacyjną w kilku kolorach (np. czerwony, żółty, niebieski, zielony). Dzieci stoją wokół chusty. Nauczyciel gra na tamburynie i mówi: „Teraz skaczemy na żółty kolor!” – dzieci przeskakują na żółte pole. Potem: „Kręcimy się na niebieskim!” – dzieci wykonują ruch na wskazanym kolorze. Stopniowo przyspieszajcie tempo. Na koniec każde dziecko wybiera swój ulubiony kolor i przez chwilę tańczy tylko na nim. Ćwiczy to koordynację i rozpoznawanie kolorów."
    },
    {
      "tytul": "Malowanie kolorowych plam – eksperymenty z farbami",
      "opis": "Każde dziecko dostaje kartkę papieru i trzy podstawowe kolory farb plakatowych (czerwony, żółty, niebieski) w małych pojemnikach. Nauczyciel pokazuje, jak zanurzyć palec w farbie i zrobić kolorową plamę. Potem dzieci mieszają kolory na kartce – obserwują, co się dzieje, gdy żółty spotka niebieski (powstaje zielony), czerwony z żółtym (pomarańczowy) itd. Na koniec każdy mówi, jaki nowy kolor odkrył. To zabawa sensoryczna i wstęp do nauki mieszania barw."
    }
  ]
}
